	bp_hs.flags = (PARITY_SET_PSH ? (FLAG_ACK) : (((FLAG_ACK) & ~(FLAG_PSH))));
	bp_hs.window = (uint16_t)((ctx->rcv_wnd >> PARITY_WSCALE));
	bp_hs.urg_ptr = 0;
	if ((bp_hs.window == 0)) {
		ctx->need_wnd_adv = true;
	}
	TCPBP_add_opt_nop(&bp_hs);
	TCPBP_add_opt_nop(&bp_hs);
	TCPBP_add_opt_ts(&bp_hs, now_ms, ctx->ts_recent);
